package generated

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// TestSource checks that the source starts with the header, the notice naming the calling test and
// the package clause, and that the body comes out formatted.
func TestSource(t *testing.T) {
	t.Parallel()

	want := "// Copyright (c) Nicholas Fedor 2026 <nick@nickfedor.com>\n" +
		"// SPDX-License-Identifier: AGPL-3.0-or-later\n\n" +
		"// Code generated by go test -run ^TestSource$ -update. DO NOT EDIT.\n\n" +
		"package demo\n\n" +
		"var values = [2]int{\n\t1, 2,\n}\n"

	assert.Equal(t, want, string(Source(t, "demo", []byte("var values = [2]int{\n1,   2,\n}\n"))))
}
